// Read-only. Returns only translations whose modified_at_timestamp is inside the window (since_ts .. now) and that are not empty.
const job = $('When called by parent').first().json;
const since = Number(job.since_ts || 0);
const errors = [];
const changed = [];
let seen = 0;
function filled(v) {
  if (v === null || v === undefined) { return false; }
  let o = v;
  if (typeof v === 'string') {
    if (!v.trim()) { return false; }
    if (v.charAt(0) !== '{') { return true; }
    try { o = JSON.parse(v); } catch (e) { return true; }
  }
  if (typeof o === 'object') { return Object.values(o).some(function (x) { return String(x || '').trim(); }); }
  return String(o).trim() !== '';
}
for (const p of $input.all()) {
  const j = p.json || {};
  if (j.error) { errors.push('Lokalise error: ' + JSON.stringify(j.error).slice(0, 200)); continue; }
  const b = j.body !== undefined ? j.body : j;
  if (!b || !Array.isArray(b.translations)) { errors.push('page without translations array: ' + JSON.stringify(b).slice(0, 200)); continue; }
  for (const t of b.translations) {
    seen++;
    if (Number(t.modified_at_timestamp || 0) < since) { continue; }
    if (!filled(t.translation)) { continue; }
    changed.push({ key_id: t.key_id, by: t.modified_by_email || '', at: Number(t.modified_at_timestamp) });
  }
}
if (!seen && !errors.length) { errors.push('no translations returned'); }
return [{ json: { project_id: job.project_id, project_name: job.project_name, iso: job.iso, lang_id: job.lang_id, en_id: job.en_id, lang_name: job.lang_name, translations_seen: seen, changed: changed, errors: errors } }];

